#include <iostream>
#include <string>
using namespace std;

int main() {
    int n;
    string ticket;

    while (cin >> n >> ticket) {
        int firstSum = 0, secondSum = 0;
        bool lucky = true;

        for (int i = 0; i < n; ++i) {
            if (ticket[i] != '4' && ticket[i] != '7') {
                lucky = false;
                break;
            }

            if (i < n / 2)
                firstSum += ticket[i] - '0';
            else
                secondSum += ticket[i] - '0';
        }

        cout << (lucky && firstSum == secondSum ? "YES\n" : "NO\n");
    }

    return 0;
}

